{
  "name": "llm_le_scan_enable_event_process",
  "confidence": "medium",
  "docstring": "Processes a BLE link-layer scan-enable state event, forwards the corresponding HCI event, updates per-interface scan state, and emits an extra state-change event when the scan state indicates disablement.",
  "subsystem": "ble",
  "var_renames": {
    "v1": "evt_ctx",
    "v2": "vif_ctx",
    "v3": "state_idx",
    "v4": "evt_buf",
    "v5": "scan_state",
    "v6": "scan_state_val",
    "v7": "scan_param",
    "v8": "state_evt_buf"
  },
  "struct_hints": [
    {
      "offset": 61,
      "meaning": "interface/link index used to select per-interface context and copied into the HCI event payload"
    },
    {
      "offset": 56,
      "meaning": "16-bit event-context field copied into HCI event payload"
    },
    {
      "offset": 58,
      "meaning": "8-bit event-context status or subfield copied into HCI event payload"
    },
    {
      "offset": 52,
      "meaning": "16-bit scan-related field, byte-swapped and stored in the scan state entry"
    },
    {
      "offset": 116,
      "meaning": "per-interface state or command index used to select the scan state table entry"
    },
    {
      "offset": 1208,
      "meaning": "state flag whose low bit controls whether an extra scan state-change event is emitted"
    },
    {
      "offset": 52,
      "meaning": "scan-state table byte storing the computed state value"
    },
    {
      "offset": 56,
      "meaning": "scan-state table field storing the byte-swapped scan parameter"
    }
  ]
}
